import{_ as l,l as s,o as e,c as o,v as t,p as n,x as i,d as A,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"MAC 与签名","description":"","frontmatter":{"title":"MAC 与签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mac-signature.md","filePath":"cs/mac-signature.md","lastUpdated":1789023840000}'),c={name:"cs/mac-signature.md"};function m(C,a,h,_,E,M){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="mac-与签名" tabindex="-1">MAC 与签名 <a class="header-anchor" href="#mac-与签名" aria-label="Permalink to &quot;MAC 与签名&quot;">​</a></h1><div class="epigraph"><p>MAC 证明「持有共享密钥的人认过这份字节」；签名证明「持有私钥的人认过」，且第三人可验。</p><footer>—— 据 Goldwasser, Micali and Rivest 对签名方案；HMAC 作为 MAC 的工程标准整理</footer></div><p><a href="/cs/hash-collision">上一课</a>给出抗碰撞哈希。本课不重证生日界。缺口是：完整与认证——谁能声称这段字节没被改、出自谁。共享密钥用 MAC；公钥侧用数字签名。两者都常先哈希再认证，但密钥用法与能否公开验证不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AEAD 已能在对称会话里绑完整。许多场景要单独的认证标签，或要<strong>不可否认</strong>：验证方没有签名私钥，不能自己伪造，却能向第三方证明。缺口不是再讲加密，而是两条原语：MAC（对称、不可公开转述为「只有某一人能做」）、签名（私钥签、公钥验）。</p><p><span class="marginnote">裸 \\(H(k\\|m)\\) 有长度扩展等问题；HMAC 把密钥与哈希组合成标准 MAC。签名则对 \\(H(m)\\) 做私钥运算，证书把公钥绑到名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MAC：输入密钥与消息，输出标签；验证即重算比较（常数时间比较，避免泄长度以外的信息——侧信道课再收）。签名：Sign\\((sk,m)\\)、Verify\\((pk,\\sigma,m)\\)。本课不选 RSA-PSS 还是 ECDSA 曲线，只锁定接口与失败含义：标签错或验签失败 ⇒ 不接受，至于是改包还是密钥错，协议层要另处理。</p>',8)),(e(),n(d,null,{default:i(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HASH%5B%22%E6%91%98%E8%A6%81%20H(m)%22%5D%20--%3E%20MAC%5B%22MAC%3A%20%E5%85%B1%E4%BA%AB%E9%94%AE%22%5D%0A%20%20HASH%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%3A%20%E7%A7%81%E9%92%A5%22%5D%0A%20%20SIG%20--%3E%20CERT%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%AF%81%E4%B9%A6%E4%B8%8E%20PKI%22%5D%0A%20%20MAC%20--%3E%20CERT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MAC 服务 CIA 的 I 与真实性（在共享密钥团体内）。签名另加不可否认与公开验证，供证书链、软件更新、2PC 之外的「这个字节来自哪一身份」。密钥泄露模型不同：MAC 密钥泄露使双方都能伪造；签名私钥泄露使全世界都能冒充，直到撤销。</p><p>常数时间比较标签，避免把比较提前返回当成侧信道；细节在侧信道课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>签名不是加密。加密的保密与签名的公开可验证可以组合（先签后封或相反），顺序有规范，本课不把每一种 CMS 变体写完。也不把「区块链签名」插入主干。时间戳、公证是额外服务。</p><p>MAC 不能转给第三方当证据：验证者自己也能造同一标签。这是不可否认缺席的精确定义。后课默认：完整性标签要么是 MAC/AEAD，要么是签名；名字如何绑到公钥，是 PKI。</p><p>验证失败应失败安全：不接受，不「尽量解密」。这与 Saltzer 的失败安全默认是同一句，对象换成标签。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>密钥泄露模型不同：MAC 团体内都能伪，签名私钥泄露则人人能冒充直到撤销。</p></li><li><p>后课证书把 \\(pk\\) 绑到名字，否则签名只证明「某把私钥」。</p></li><li><p>哈希是零件；MAC 用共享键认证，签名可公开验证。</p></li><li><p>不可否认是签名相对 MAC 的差额，不是更长的摘要。</p></li><li><p>公钥如何被相信属于某个名字，是证书课缺口。</p></li><li><p>出处：Goldwasser, Micali and Rivest；RFC 2104 HMAC；Stallings。</p></li></ul>',9))])}const f=l(c,[["render",m]]);export{S as __pageData,f as default};
